SELECT category, CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, MAX(stock_qty) AS max_stock_qty, COUNT(stock_qty) AS stock_qty_count FROM products WHERE category NOT IN ('Fashion', 'Grocery') AND brand IN ('Globex', 'Umbrella', 'Stark') GROUP BY category, CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END
